// Lookup finds a model's published rate. raw is whatever the harness said; it is
// canonicalised the same way every other model reading on the page is, so a
// dated build and a gateway route find the row their family has.
//
// A miss is not an error and not a zero — it is the honest answer for a model
// nobody published a price for, and every caller must treat it as "no estimate"
// rather than "free".
func Lookup(raw string) (Rate, bool) {
	key := modelid.Key(raw)
	if r, ok := published.Models[key]; ok {
		return r, true
	}
	r, ok := rates[key]
	return r, ok
}

// Estimate prices one session's tokens. fresh, cacheWrite and cacheRead are the
// three classes of input the transcript reports apart (capture.TokenUsage); out
// is what the model produced.
//
// A model with no published rate estimates nothing, and says so, rather than
// returning a confident zero.
func Estimate(raw string, fresh, cacheWrite, cacheRead, out int) (float64, bool) {
	r, ok := Lookup(raw)
	if !ok {
		return 0, false
	}
	const perToken = 1_000_000.0
	usd := (float64(fresh)*r.In +
		float64(cacheWrite)*r.CacheWrite +
		float64(cacheRead)*r.CacheRead +
		float64(out)*r.Out) / perToken
	return usd, true
}

// Models is how many models can be priced at all, for a page that wants to say
// how far its coverage reaches without listing every row. The two sources
// overlap, so this counts the union rather than adding them.
func Models() int {
	seen := make(map[string]bool, len(published.Models)+len(rates))
	for k := range published.Models {
		seen[k] = true
	}
	for k := range rates {
		seen[k] = true
	}
	return len(seen)
}
